function updateOverviewCopy(){const target=document.querySelector('#overview-copy');if(!target||!data)return;if(!lastOverviewCopy){const previous=localStorage.getItem('overview-copy-previous')||'',input={summary:data.summary,resources,liveEvents:liveActivity,capabilities:data.capabilities,lastMessage:previous},copy=overviewCopy(input);lastOverviewCopy=sessionOverviewCopy(lastOverviewCopy,input);localStorage.setItem('overview-copy-previous',lastOverviewCopy);target.dataset.kind=copy.kind}target.textContent=lastOverviewCopy}
function updateResources(){if(!resources)return;const ram=document.querySelector('#resource-ram'),cpu=document.querySelector('#resource-cpu'),dashboard=document.querySelector('#resource-dashboard'),dashboardMeta=document.querySelector('#resource-dashboard-meta');if(!ram)return;ram.textContent=resources.ram?.total?`${bytes(resources.ram.used)} / ${bytes(resources.ram.total)}`:'Unavailable';cpu.textContent=resources.cpuPercent==null?'Unavailable':`${resources.cpuPercent.toFixed(0)}%`;dashboard.textContent=resources.dashboard?.rss?bytes(resources.dashboard.rss):'Unavailable';dashboardMeta.textContent=resources.dashboard?.cpuPercent==null?'Local server':`${resources.dashboard.cpuPercent.toFixed(1)}% CPU · local server`;ram.closest('[data-resource]')?.style.setProperty('--level',`${Math.max(0,Math.min(100,(resources.ram?.ratio||0)*100))}%`);cpu.closest('[data-resource]')?.style.setProperty('--level',`${Math.max(0,Math.min(100,resources.cpuPercent||0))}%`);updateOverviewCopy()}
