function capacityPanel(){const providers=capacity?.providers||[],available=providers.filter(provider=>['Available','Stale'].includes(provider.status)),other=providers.filter(provider=>!['Available','Stale'].includes(provider.status));return `<section class="capacity-panel"><header><div><span class="kicker">PLAN CAPACITY</span><h3>Remaining allowance</h3></div><p>Account/capacity-source telemetry only. Separate from models and token analytics.</p></header><div class="capacity-layout"><div class="capacity-available">${available.map(provider=>provider.windows.map(window=>{const remaining=Math.max(0,Math.min(100,Number(window.remainingPercent)||0));return `<article class="capacity-card"><div class="capacity-primary"><div><span>${esc(provider.provider)}</span><strong>${esc(window.label)} remaining${provider.status==='Stale'?' · stale':''}</strong></div><b>${remaining.toFixed(0)}%</b></div><div class="capacity-track" role="progressbar" aria-label="${esc(provider.provider)} ${esc(window.label)} remaining" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${remaining.toFixed(0)}"><i style="width:${remaining}%"></i></div><div class="capacity-meta"><span>${window.resetAt?`Resets ${esc(resetTime(window.resetAt))}`:'Reset time unavailable'}</span><time title="${esc(provider.observedAt||'')}">${provider.observedAt?`Updated ${esc(clock(provider.observedAt))}`:'Update time unavailable'}</time></div>${capacityAction(provider.action)}</article>`}).join('')).join('')||`<div class="capacity-empty">No supported plan-capacity source is currently available.</div>`}</div><div class="capacity-unavailable-list">${other.map(provider=>`<article data-capacity-status="${esc(provider.status)}"><div><strong>${esc(provider.provider)}</strong><span>${esc(provider.status)}${provider.message?`: ${esc(provider.message)}`:''}</span></div>${capacityAction(provider.action)}</article>`).join('')}</div></div></section>`}
