  let reportVisible=false;
  layer.querySelector('#bug-review-report').onclick=()=>{reportVisible=!reportVisible;reportPreview.textContent=reportText();reportPreview.hidden=!reportVisible;layer.querySelector('#bug-review-report').textContent=reportVisible?'Hide report':'Review report'};
