async function setupDrawer(layer){const c=layer.querySelector('#drawer-content');c.innerHTML=`<p class="drawer-intro">Choose the format that fits your goal. Public exports never include project names, notes, paths, prompts, transcripts, or credentials.</p><div class="goal-list"><button data-export="stack"><strong>Share Stack</strong><span>A privacy-safe representation of the agents and capabilities you use.</span></button><button data-prompt><strong>Setup Prompt</strong><span>A current prompt for another AI agent to safely audit and adapt this stack.</span></button><button data-export="manifest"><strong>Manifest</strong><span>Machine-readable interoperability for a future dashboard import.</span></button><button data-export="private"><strong>Private Backup</strong><span>Detailed local audit inventory. Never share.</span></button></div><div id="prompt-preview"></div>`;c.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>download(await(await fetch(`/api/export/${b.dataset.export}`)).text(),`ai-development-${b.dataset.export}.json`));c.querySelector('[data-prompt]').onclick=async()=>{const prompt=await(await fetch('/api/export/setup-prompt')).text();c.querySelector('#prompt-preview').innerHTML=`<h3>Setup Prompt</h3><textarea readonly>${esc(prompt)}</textarea><div><button class="primary" id="copy-prompt">Copy prompt</button><button class="text-action" id="download-prompt">Download prompt</button></div>`;c.querySelector('#copy-prompt').onclick=()=>navigator.clipboard.writeText(prompt);c.querySelector('#download-prompt').onclick=()=>download(prompt,'ai-development-setup-prompt.txt','text/plain')}}
