function comparisonSection(x){const cohorts=(x.comparisons?.cohorts||[]).filter(c=>['strongly-matched','controlled'].includes(c.classification));const value=v=>v==null?'—':short(v);if(!cohorts.length)return `<section class="panel comparison-panel comparison-empty"><div class="section-head"><div><span class="kicker">COMPARABLE OBSERVATIONS</span><h3>No comparable observations yet.</h3><p>Normal work is still observed. For a private comparison, select a work block, name one objective, choose an observed validation target, and work normally.</p></div><button class="text-action" data-eff-start-comparison>Start comparison cycle</button></div><small>Session proxies and historical validator records are descriptive only; they are not silently promoted to tasks or outcomes.</small></section>`;return `<section class="panel comparison-panel"><div class="section-head"><div><span class="kicker">COMPARABLE OBSERVATIONS</span><h3>Matched evidence, not a ranking.</h3><p>Only explicit cycles with compatible validators and known execution paths appear here.</p></div><span class="quiet">Private only</span></div>${cohorts.map(cohort=>{const contract=cohort.validationContract||{},exclusions=cohort.exclusions||[];return `<article class="comparison-cohort"><div class="comparison-title"><div><strong>${cohort.evidenceLevel}</strong><small>${esc(cohort.gate?.label||'Evidence pending')}</small></div><button class="text-action" data-eff-why="${esc(cohort.cohortId)}">Why comparable?</button></div><p>${cohort.classification==='controlled'?'Controlled task/benchmark evidence.':'Same private objective, project, and validation contract; observational, not controlled.'}</p><small>Validation: ${esc(contract.kind||'Unknown')} · ${esc(contract.strength||'Unknown')} · ${esc(contract.targetId||'Unknown')}</small><div class="comparison-table"><div class="comparison-head"><span>Execution path</span><span>n</span><span>Median Fresh + Output</span><span>Attempts</span><span>Validated</span><span>Exact cost</span></div>${cohort.variants.map(variant=>{const m=variant.metrics||{},identity=variant.identity||{},cost=m.exactCostUntilValidation?.median;return `<div class="comparison-row"><span><strong>${esc(identity.model||identity.modelId||'Unknown model')}</strong><small>${esc(identity.provider||'Unknown provider')} · via ${esc(identity.host||'Unknown host')}</small></span><span>${fmt(m.observations)}</span><span>${value(m.freshPlusOutput?.median)}${m.freshPlusOutput?.iqr?` <small>${value(m.freshPlusOutput.iqr.p25)}–${value(m.freshPlusOutput.iqr.p75)}</small>`:''}</span><span>${value(m.attempts?.median)}</span><span>${fmt(m.validatedOutcomes)}/${fmt(m.observations)}</span><span>${cost==null?'Unavailable':`$${cost.toFixed(2)}`}</span></div>`}).join('')}</div>${cohort.gate?.percentageAllowed&&cohort.percentages?.freshPlusOutput!=null?`<p class="comparison-note">Median Fresh + Output was ${Math.abs(Math.round(cohort.percentages.freshPlusOutput*100))}% ${cohort.percentages.freshPlusOutput<0?'lower':'higher'} in this ${cohort.classification==='controlled'?'controlled trial':'strongly matched observational cohort'}.</p>`:`<p class="comparison-note">${esc(cohort.gate?.label||'Limited evidence')} — raw distributions and coverage remain more informative than a percentage claim.</p>`}<details class="comparison-exclusions"><summary>Excluded ${exclusions.length}</summary>${exclusions.length?`<ul>${exclusions.map(item=>`<li>${esc(item.reasonCode)}</li>`).join('')}</ul>`:'<p>No recorded exclusions.</p>'}</details></article>`}).join('')}</section>`}
function bindEfficiencyComparisons(){const review=document.querySelector('.efficiency-review'),x=efficiencyData;if(!review||!x)return;document.querySelector('.comparison-panel')?.remove();review.insertAdjacentHTML('beforebegin',comparisonSection(x));document.querySelector('[data-eff-start-comparison]')?.addEventListener('click',()=>{review.scrollIntoView({behavior:'smooth',block:'start'});review.querySelector('[data-eff-private-label]')?.focus()});const head=review.querySelector('.section-head');if(head&&!review.querySelector('.comparison-cycle-fields'))head.insertAdjacentHTML('afterend',`<div class="comparison-cycle-fields"><label>Private objective<input data-eff-private-label maxlength="160" placeholder="Same label for comparable runs"></label><label>Validation target<select data-eff-contract>${(x.validationContracts||[]).map((contract,index)=>`<option value="${index}">${esc(contract.kind)} · ${esc(contract.strength)} · ${esc(contract.targetId)}</option>`).join('')||'<option value="">No observed validator in this period</option>'}</select></label><label class="comparison-check"><input type="checkbox" data-eff-capability-known> Capability configuration is known and matched</label></div>`);const original=review.querySelector('[data-eff-create-cycle]');if(original&&!original.dataset.comparisonBound){const button=original.cloneNode(true);button.dataset.comparisonBound='true';button.textContent='Save comparison cycle';original.replaceWith(button);button.addEventListener('click',async()=>{const workBlockIds=[...review.querySelectorAll('[data-eff-cycle-block]:checked')].map(input=>input.dataset.effCycleBlock),privateLabel=review.querySelector('[data-eff-private-label]')?.value.trim(),contractIndex=review.querySelector('[data-eff-contract]')?.value,validationContract=(x.validationContracts||[])[Number(contractIndex)];if(!privateLabel){alert('Add a private objective before creating a comparison cycle.');return}if(!validationContract){alert('Choose an observed validation target before creating a comparison cycle.');return}const response=await fetch('/api/efficiency/cycles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workBlockIds,privateLabel,validationContract,capabilityConfigurationKnown:review.querySelector('[data-eff-capability-known]')?.checked===true})}),result=await response.json();if(result.error){alert(result.error);return}data=await(await fetch('/api/data')).json();efficiencyData=null;render()})}document.querySelectorAll('[data-eff-why]').forEach(button=>button.addEventListener('click',()=>{const cohort=(x.comparisons?.cohorts||[]).find(item=>item.cohortId===button.dataset.effWhy);if(!cohort)return;alert(`Cohort: ${cohort.evidenceLevel}\nMatched by: explicit objective, project, validation contract, and execution path\nValidation: ${cohort.validationContract?.kind||'Unknown'} · ${cohort.validationContract?.strength||'Unknown'}\nSample: ${cohort.variants.map(v=>v.metrics?.observations||0).join(' vs ')}\nLimitations: ${cohort.classification==='controlled'?'controlled evidence, limited to this trial.':'observational, not controlled.'}`)}))}
function render(){applyAccent(settings?.appearance?.accent);if(detailId){const p=project(detailId);if(p){stopMonitor();return projectDetail(p);}detailId=null}if(view!=='live')stopMonitor();if(view==='overview')overview();else if(view==='live')liveFeed();else if(view==='projects')projects();else if(view==='capabilities')capabilities();else if(view==='efficiency'){efficiency();setTimeout(()=>{bindEfficiencyCycles();bindEfficiencyComparisons()},0)}else maintenance()}
async function refreshUI(){try{const next=await(await fetch('/api/data')).json();if(!data||next.summary.lastScanAt!==data.summary.lastScanAt){data=next;live.textContent=`Dashboard live · updated ${ago(data.summary.lastScanAt)}`;if(!utility)render()}}catch{}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>activateView(b.dataset.view));document.querySelector('#search').oninput=e=>{term=e.target.value;render()};document.querySelector('#setup').onclick=()=>toggleDrawer('setup');document.querySelector('#share').onclick=()=>toggleDrawer('share');document.querySelector('#report-bug').onclick=openBugReport;document.querySelector('#rescan').onclick=async()=>{const b=document.querySelector('#rescan');b.textContent='…';await fetch('/api/scan',{method:'POST'});await refreshUI();b.textContent='↻'};data=await(await fetch('/api/data')).json();try{const state=await(await fetch(`/api/live-state?at=${Date.now()}`,{cache:'no-store'})).json();resources=state.system;capacity=state.capacity;liveActivity=state.activity?.events||[];operator=state.operator||null;detectedAgents=state.agents||null}catch{}try{release=await(await fetch('/api/release')).json();settings=await(await fetch('/api/settings')).json();openRouter=await(await fetch('/api/openrouter')).json()}catch{release=release||{author:'Eric Barker',year:2026,personalSite:'https://ericbarker.co',articleUrl:'https://designdelulu.com/blog/ai-development-dashboard.html',organizationUrl:'https://designdelulu.com',organizationName:'Design Delulu',repositoryPublic:false};settings=settings||{projectsRoots:[],needsProjectRoot:false};openRouter=openRouter||{enabled:false}}document.querySelector('#app-footer').innerHTML=footerMarkup(release);live.textContent=`Dashboard live · updated ${ago(data.summary.lastScanAt)}`;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));render();updateLiveFeedSignal();setInterval(refreshUI,15000);setInterval(refreshLiveState,2_000);
